-- Smartphones
('prd-001', 'iPhone 16 Pro Max', 'আইফোন ১৬ প্রো ম্যাক্স', 'iphone-16-pro-max', 'The most powerful iPhone ever with A18 Pro chip, 48MP camera system, and titanium design. Features a 6.9" Super Retina XDR display with ProMotion.', 'সর্বাধিক শক্তিশালী আইফোন A18 প্রো চিপ, 48MP ক্যামেরা সিস্টেম এবং টাইটানিয়াম ডিজাইন সহ। ৬.৯" সুপার রেটিনা XDR ডিসপ্লে প্রোমোশন সহ।', 'iPhone 16 Pro Max - A18 Pro, 48MP Camera', 'আইফোন ১৬ প্রো ম্যাক্স - A18 প্রো, 48MP ক্যামেরা', 159900, 179900, 120000, 'APL-IP16PM-256', 25, 5, 'cat-008', 'brd-001', 'https://images.unsplash.com/photo-1695048133142-1a20484d2569?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1695048133142-1a20484d2569?w=800","https://images.unsplash.com/photo-1592750475338-74b7b21085ab?w=800"]', 1, 1, 227, 480, 45, 'iPhone 16 Pro Max 256GB', 'Buy iPhone 16 Pro Max in Bangladesh', '2025-01-15T00:00:00.000Z', '2025-01-15T00:00:00.000Z'),
('prd-002', 'Samsung Galaxy S25 Ultra', 'স্যামসাং গ্যালাক্সি S25 আল্ট্রা', 'samsung-galaxy-s25-ultra', 'Samsung flagship with Snapdragon 8 Elite, 200MP camera, S Pen, and 6.9" Dynamic AMOLED 2X display. Titanium frame with IP68 rating.', 'স্যামসাং ফ্ল্যাগশিপ Snapdragon 8 Elite, 200MP ক্যামেরা, S Pen এবং ৬.৯" ডায়নামিক AMOLED 2X ডিসপ্লে সহ।', 'Galaxy S25 Ultra - 200MP, S Pen', 'গ্যালাক্সি S25 আল্ট্রা - 200MP, S Pen', 139900, 159900, 105000, 'SAM-S25U-256', 30, 5, 'cat-009', 'brd-002', 'https://images.unsplash.com/photo-1610945415295-d9bbf067e59c?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1610945415295-d9bbf067e59c?w=800"]', 1, 1, 218, 470, 38, 'Samsung Galaxy S25 Ultra', 'Buy Samsung Galaxy S25 Ultra in BD', '2025-01-20T00:00:00.000Z', '2025-01-20T00:00:00.000Z'),
('prd-003', 'Xiaomi 15 Ultra', 'শাওমি ১৫ আল্ট্রা', 'xiaomi-15-ultra', 'Leica-powered quad camera, Snapdragon 8 Elite, 6.73" 2K LTPO AMOLED. Premium design with 5000mAh battery and 90W fast charging.', 'Leica-চালিত কোয়াড ক্যামেরা, Snapdragon 8 Elite, ৬.৭৩" 2K LTPO AMOLED।', 'Xiaomi 15 Ultra - Leica Camera', 'শাওমি ১৫ আল্ট্রা - Leica ক্যামেরা', 89900, 99900, 68000, 'XMI-15U-256', 20, 5, 'cat-009', 'brd-003', 'https://images.unsplash.com/photo-1598327105666-5b89351aff97?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1598327105666-5b89351aff97?w=800"]', 1, 1, 225, 460, 22, 'Xiaomi 15 Ultra Price in BD', 'Buy Xiaomi 15 Ultra Bangladesh', '2025-02-01T00:00:00.000Z', '2025-02-01T00:00:00.000Z'),
('prd-004', 'OnePlus 13', 'ওয়ানপ্লাস ১৩', 'oneplus-13', 'Snapdragon 8 Elite, 50MP triple camera with Hasselblad, 6.82" 2K LTPO AMOLED, 6000mAh battery with 100W SUPERVOOC charging.', 'Snapdragon 8 Elite, Hasselblad ৫০MP ত্রিক্যামেরা, ৬.৮২" 2K LTPO AMOLED', 'OnePlus 13 - Hasselblad Camera', 'ওয়ানপ্লাস ১৩ - Hasselblad ক্যামেরা', 69900, 79900, 52000, 'OP-13-256', 35, 5, 'cat-009', 'brd-007', 'https://images.unsplash.com/photo-1565849904461-04a58adcb756?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1565849904461-04a58adcb756?w=800"]', 1, 0, 213, 450, 18, 'OnePlus 13 Price in BD', 'OnePlus 13 buy online Bangladesh', '2025-01-25T00:00:00.000Z', '2025-01-25T00:00:00.000Z'),
('prd-005', 'Nothing Phone (3a)', 'নাথিং ফোন (৩এ)', 'nothing-phone-3a', 'Unique Glyph Interface, Snapdragon 7s Gen 3, 50MP dual camera, 6.8" AMOLED 120Hz. Transparent back design with LED glyph patterns.', 'অনন্য গ্লিফ ইন্টারফেস, Snapdragon 7s Gen 3, ৫০MP ডুয়াল ক্যামেরা', 'Nothing Phone 3a - Glyph Design', 'নাথিং ফোন ৩এ - গ্লিফ ডিজাইন', 32900, 37900, 24000, 'NOT-P3A-128', 40, 5, 'cat-009', 'brd-008', 'https://images.unsplash.com/photo-1592899677977-9c10ca588bbd?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1592899677977-9c10ca588bbd?w=800"]', 1, 0, 190, 430, 12, 'Nothing Phone 3a BD Price', 'Buy Nothing Phone 3a Bangladesh', '2025-03-01T00:00:00.000Z', '2025-03-01T00:00:00.000Z'),

