('prd-006', 'MacBook Pro 16" M4 Max', 'ম্যাকবুক প্রো ১৬" M4 Max', 'macbook-pro-16-m4-max', 'Apple M4 Max chip with 16-core CPU and 40-core GPU. 36GB unified memory, 1TB SSD. Stunning 16" Liquid Retina XDR display.', 'Apple M4 Max চিপ ১৬-কোর CPU এবং ৪০-কোর GPU সহ। ৩৬GB ইউনিফাইড মেমরি, ১TB SSD।', 'MacBook Pro 16" - M4 Max, 36GB RAM', 'ম্যাকবুক প্রো ১৬" - M4 Max, 36GB RAM', 349900, 379900, 265000, 'APL-MBP16-M4MAX', 10, 3, 'cat-002', 'brd-001', 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=800"]', 1, 1, 2140, 490, 28, 'MacBook Pro 16 M4 Max Price', 'Buy MacBook Pro M4 Max Bangladesh', '2025-01-10T00:00:00.000Z', '2025-01-10T00:00:00.000Z'),
('prd-007', 'Dell XPS 15 (2025)', 'ডেল XPS ১৫ (২০২৫)', 'dell-xps-15-2025', 'Intel Core Ultra 9, NVIDIA RTX 4070, 32GB RAM, 1TB SSD. 15.6" 3.5K OLED InfinityEdge display. Premium CNC aluminum chassis.', 'Intel Core Ultra 9, NVIDIA RTX 4070, ৩২GB RAM, ১TB SSD। ১৫.৬" ৩.৫K OLED ডিসপ্লে।', 'Dell XPS 15 - Ultra 9, RTX 4070', 'ডেল XPS ১৫ - Ultra 9, RTX 4070', 189900, 209900, 142000, 'DEL-XPS15-U9', 15, 3, 'cat-002', 'brd-005', 'https://images.unsplash.com/photo-1593642702821-c8da6771f0c6?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1593642702821-c8da6771f0c6?w=800"]', 1, 1, 1860, 470, 19, 'Dell XPS 15 2025 Price BD', 'Dell XPS 15 buy online Bangladesh', '2025-02-15T00:00:00.000Z', '2025-02-15T00:00:00.000Z'),
('prd-008', 'ASUS ROG Zephyrus G16', 'এএসআস ROG জেফাইরাস G16', 'asus-rog-zephyrus-g16', 'Intel Core Ultra 9 285H, RTX 5080, 32GB DDR5, 1TB SSD. 16" 240Hz OLED display. Ultra-slim gaming powerhouse.', 'Intel Core Ultra 9 285H, RTX 5080, ৩২GB DDR5, ১TB SSD। ১৬" 240Hz OLED ডিসপ্লে।', 'ROG Zephyrus G16 - RTX 5080', 'ROG জেফাইরাস G১৬ - RTX 5080', 249900, 279900, 188000, 'ASUS-ROG-G16', 8, 3, 'cat-010', 'brd-002', 'https://images.unsplash.com/photo-1625842268584-8f3296236761?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1625842268584-8f3296236761?w=800"]', 1, 1, 1850, 480, 15, 'ASUS ROG Zephyrus G16 Price', 'Buy ROG Zephyrus G16 Bangladesh', '2025-03-10T00:00:00.000Z', '2025-03-10T00:00:00.000Z'),

-- Audio
('prd-009', 'Sony WH-1000XM6', 'সনি WH-1000XM6', 'sony-wh-1000xm6', 'Industry-leading noise cancellation with Auto NC Optimizer. 30-hour battery, Hi-Res Audio, multipoint connection. Ultra-comfortable design.', 'শিল্পের নেতৃস্থানীয় নয়েজ ক্যানসেলেশন Auto NC Optimizer সহ। ৩০ ঘণ্টা ব্যাটারি।', 'Sony WH-1000XM6 - Best ANC', 'সনি WH-1000XM6 - সেরা ANC', 34900, 39900, 26000, 'SON-WH1000XM6', 50, 10, 'cat-003', 'brd-004', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=800"]', 1, 1, 250, 485, 62, 'Sony WH-1000XM6 Price BD', 'Buy Sony WH-1000XM6 Bangladesh', '2025-01-20T00:00:00.000Z', '2025-01-20T00:00:00.000Z'),
('prd-010', 'Apple AirPods Pro 3', 'অ্যাপল এয়ারপডস প্রো ৩', 'apple-airpods-pro-3', 'Active Noise Cancellation with Adaptive Transparency. Personalized Spatial Audio. USB-C, IP54 rated. Up to 6 hours listening time.', 'অ্যাক্টিভ নয়েজ ক্যানসেলেশন অ্যাডাপ্টিভ ট্রান্সপারেন্সি সহ। পার্সোনালাইজড স্পেশিয়াল অডিও।', 'AirPods Pro 3 - ANC, Spatial Audio', 'এয়ারপডস প্রো ৩ - ANC, স্পেশিয়াল অডিও', 29900, 32900, 22000, 'APL-APP3', 60, 10, 'cat-011', 'brd-001', 'https://images.unsplash.com/photo-1606220945770-b5b6c2c55bf1?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1606220945770-b5b6c2c55bf1?w=800"]', 1, 1, 50, 475, 78, 'AirPods Pro 3 Price BD', 'Apple AirPods Pro 3 buy Bangladesh', '2025-02-01T00:00:00.000Z', '2025-02-01T00:00:00.000Z'),
('prd-011', 'JBL Charge 5', 'জেবিএল চার্জ ৫', 'jbl-charge-5', 'Portable Bluetooth speaker with powerful JBL Original Pro Sound. IP67 waterproof and dustproof. 20 hours of playtime. Built-in powerbank.', 'পোর্টেবল ব্লুটুথ স্পিকার শক্তিশালী JBL অরিজিনাল প্রো সাউন্ড সহ। IP67 ওয়াটারপ্রুফ।', 'JBL Charge 5 - Waterproof Speaker', 'JBL চার্জ ৫ - ওয়াটারপ্রুফ স্পিকার', 16900, 19900, 12500, 'JBL-CH5-BLK', 45, 10, 'cat-003', 'brd-009', 'https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?w=800"]', 1, 0, 960, 460, 35, 'JBL Charge 5 Price BD', 'Buy JBL Charge 5 Bangladesh', '2025-01-05T00:00:00.000Z', '2025-01-05T00:00:00.000Z'),

-- Wearables
('prd-012', 'Apple Watch Ultra 3', 'অ্যাপল ওয়াচ আল্ট্রা ৩', 'apple-watch-ultra-3', 'The most rugged Apple Watch. 49mm titanium case, precision dual-frequency GPS, up to 36 hours battery. Water resistant to 100m.', 'সবচেয়ে টেকসই অ্যাপল ওয়াচ। ৪৯মিমি টাইটানিয়াম কেস, প্রিসিশন GPS', 'Apple Watch Ultra 3 - 49mm Titanium', 'অ্যাপল ওয়াচ আল্ট্রা ৩ - ৪৯মিমি টাইটানিয়াম', 89900, 99900, 67000, 'APL-AWU3-49', 20, 5, 'cat-004', 'brd-001', 'https://images.unsplash.com/photo-1434493789847-2f02dc6ca35d?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1434493789847-2f02dc6ca35d?w=800"]', 1, 1, 614, 480, 32, 'Apple Watch Ultra 3 Price BD', 'Buy Apple Watch Ultra 3 Bangladesh', '2025-02-10T00:00:00.000Z', '2025-02-10T00:00:00.000Z'),
('prd-013', 'Samsung Galaxy Watch 7', 'স্যামসাং গ্যালাক্সি ওয়াচ ৭', 'samsung-galaxy-watch-7', 'Advanced BioActive Sensor for heart rate, blood oxygen, body composition. Wear OS 5, sapphire crystal glass, IP68.', 'অ্যাডভান্সড বায়োঅ্যাক্টিভ সেন্সার হৃদযন্ত্রের স্পন্দন, রক্তে অক্সিজেন পরিমাপের জন্য।', 'Galaxy Watch 7 - BioActive Sensor', 'গ্যালাক্সি ওয়াচ ৭ - বায়োঅ্যাক্টিভ সেন্সার', 32900, 37900, 24500, 'SAM-GW7-44', 30, 5, 'cat-004', 'brd-002', 'https://images.unsplash.com/photo-1579586337278-3befd40fd17a?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1579586337278-3befd40fd17a?w=800"]', 1, 0, 288, 440, 18, 'Galaxy Watch 7 Price BD', 'Samsung Galaxy Watch 7 buy BD', '2025-01-25T00:00:00.000Z', '2025-01-25T00:00:00.000Z'),

-- Accessories
('prd-014', 'Anker Nano II 65W', 'অ্যাংকার ন্যানো II ৬৫W', 'anker-nano-ii-65w', 'Ultra-compact GaN charger with 65W USB-C Power Delivery. Charges MacBook, iPhone, and iPad simultaneously. foldable prongs.', 'আল্ট্রা-কম্প্যাক্ট GaN চার্জার ৬৫W USB-C পাওয়ার ডেলিভারি সহ।', 'Anker Nano II 65W GaN Charger', 'অ্যাংকার ন্যানো II ৬৫W GaN চার্জার', 4900, 6500, 3200, 'ANK-N65W', 100, 20, 'cat-005', 'brd-010', 'https://images.unsplash.com/photo-1583394838336-acd977736f90?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1583394838336-acd977736f90?w=800"]', 1, 0, 120, 450, 42, 'Anker Nano II 65W Price', 'Anker 65W charger Bangladesh', '2025-01-10T00:00:00.000Z', '2025-01-10T00:00:00.000Z'),
('prd-015', 'Spigen MagSafe Case iPhone 16', 'স্পাইগেন MagSafe কেস আইফোন ১৬', 'spigen-magsafe-iphone-16', 'Military-grade protection with MagSafe compatibility. Air Cushion technology for drop protection. Slim profile with precise cutouts.', 'মিলিটারি-গ্রেড প্রোটেকশন MagSafe সামঞ্জস্য সহ। ড্রপ প্রোটেকশনের জন্য এয়ার কুশন টেকনোলজি।', 'Spigen MagSafe Case - iPhone 16', 'স্পাইগেন MagSafe কেস - আইফোন ১৬', 2900, 3900, 1500, 'SPI-MF-IP16', 80, 20, 'cat-005', 'brd-001', 'https://images.unsplash.com/photo-1601784551446-20c9e07cdbdb?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1601784551446-20c9e07cdbdb?w=800"]', 1, 0, 45, 440, 28, 'Spigen MagSafe Case iPhone 16', 'Buy Spigen iPhone 16 case BD', '2025-01-15T00:00:00.000Z', '2025-01-15T00:00:00.000Z'),

-- Gaming
('prd-016', 'PlayStation 5 Pro', 'প্লেস্টেশন ৫ প্রো', 'playstation-5-pro', 'Enhanced GPU with 67% more compute units. 2TB SSD, 8K support, ray tracing. DualSense controller included.', 'এনহান্সড GPU ৬৭% বেশি কম্পিউট ইউনিট সহ। 2TB SSD, 8K সাপোর্ট।', 'PS5 Pro - 2TB, DualSense', 'PS৫ প্রো - 2TB, DualSense', 89900, 99900, 67000, 'SON-PS5PRO-2TB', 15, 5, 'cat-006', 'brd-004', 'https://images.unsplash.com/photo-1606144042614-b2417e99c4e3?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1606144042614-b2417e99c4e3?w=800"]', 1, 1, 3200, 490, 55, 'PS5 Pro Price BD', 'Buy PlayStation 5 Pro Bangladesh', '2025-01-01T00:00:00.000Z', '2025-01-01T00:00:00.000Z'),
('prd-017', 'Nintendo Switch 2', 'নিন্টেন্ডো সুইচ ২', 'nintendo-switch-2', 'Next-gen hybrid console. 8-inch LCD, magnetic Joy-Cons, 1080p handheld / 4K docked. backwards compatible.', 'পরবর্তী প্রজন্রের হাইব্রিড কনসোল। ৮-ইঞ্চি LCD, ম্যাগনেটিক Joy-Cons', 'Nintendo Switch 2 - 8" LCD', 'নিন্টেন্ডো সুইচ ২ - ৮" LCD', 49900, 54900, 37000, 'NIN-SW2-256', 25, 5, 'cat-006', 'brd-004', 'https://images.unsplash.com/photo-1578303512597-81e6cc155b3e?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1578303512597-81e6cc155b3e?w=800"]', 1, 1, 400, 470, 40, 'Nintendo Switch 2 Price BD', 'Buy Nintendo Switch 2 Bangladesh', '2025-06-01T00:00:00.000Z', '2025-06-01T00:00:00.000Z'),

-- Cameras
('prd-018', 'Sony A7 IV', 'সনি A7 IV', 'sony-a7-iv', '33MP full-frame Exmor R sensor, BIONZ XR processor, 4K 60fps, 10fps continuous shooting, 5-axis IBIS.', '৩৩MP ফুল-ফ্রেম Exmor R সেন্সার, BIONZ XR প্রসেসর, 4K 60fps', 'Sony A7 IV - 33MP Full Frame', 'সনি A7 IV - ৩৩MP ফুল ফ্রেম', 229900, 249900, 172000, 'SON-A7IV-BODY', 8, 3, 'cat-007', 'brd-004', 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1516035069371-29a1b244cc32?w=800"]', 1, 1, 658, 475, 22, 'Sony A7 IV Price BD', 'Buy Sony A7 IV Bangladesh', '2025-02-01T00:00:00.000Z', '2025-02-01T00:00:00.000Z'),

-- More products for variety
('prd-019', 'HP Spectre x360 14', 'এইচপি স্পেক্ট্র x360 ১৪', 'hp-spectre-x360-14', 'Intel Core Ultra 7, 32GB RAM, 1TB SSD. 14" 2.8K OLED touchscreen, 360° hinge. Gem-cut design with Thunderbolt 4.', 'Intel Core Ultra 7, ৩২GB RAM, ১TB SSD। ১৪" ২.৮K OLED টাচস্ক্রিন', 'HP Spectre x360 14 - Ultra 7, OLED', 'HP স্পেক্ট্র x360 ১৪ - Ultra 7, OLED', 159900, 179900, 120000, 'HP-SPEC-X360', 12, 3, 'cat-002', 'brd-006', 'https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=600&h=600&fit=crop', '["https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=800"]', 1, 0, 1360, 455, 14, 'HP Spectre x360 14 Price BD', 'Buy HP Spectre x360 Bangladesh', '2025-03-01T00:00:00.000Z', '2025-03-01T00:00:00.000Z'),
