('hero-002', 'Galaxy S25 Ultra', 'গ্যালাক্সি S25 আল্ট্রা', 'The next S Pen experience', 'পরবর্তী S Pen অভিজ্ঞতা', 'Write, sketch, and create with AI-powered S Pen', 'AI-চালিত S Pen দিয়ে লিখুন, আঁকুন এবং তৈরি করুন', 'https://images.unsplash.com/photo-1610945415295-d9bbf067e59c?w=1200&h=600&fit=crop', '', '', 'Explore', 'অনুসন্ধান করুন', '/products/samsung-galaxy-s25-ultra', '', '', '', 'rgba(0,0,0,0.4)', 'left', '#FFFFFF', 'Flagship', 'ফ্ল্যাগশিপ', 'secondary', 'fade', 700, 'xl', 'md', 'prd-002', 1, 1, 1, 2, 1, '2025-01-01T00:00:00.000Z', '2025-01-01T00:00:00.000Z'),
('hero-003', 'MacBook Pro with M4', 'ম্যাকবুক প্রো M4 দিয়ে', 'Mind-blowing. Head-turning.', 'মন বিস্ময়কর। মাথা ঘোরানো।', 'The most advanced Mac laptops ever.', 'সর্বাধিক উন্নত ম্যাক ল্যাপটপ।', 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=1200&h=600&fit=crop', '', '', 'Buy Now', 'এখনই কিনুন', '/products/macbook-pro-16-m4-max', '', '', '', 'rgba(0,0,0,0.35)', 'center', '#FFFFFF', 'Best Seller', 'সর্বাধিক বিক্রি', 'default', 'fade', 700, 'xl', 'md', 'prd-006', 1, 1, 1, 3, 1, '2025-01-01T00:00:00.000Z', '2025-01-01T00:00:00.000Z'),
('hero-004', 'Summer Mega Sale', 'গ্রীষ্মকালীন মেগা সেল', 'Up to 40% off on accessories', 'অ্যাক্সেসরিজে ৪০% পর্যন্ত ছাড়', 'Limited time offer on top brands', 'শীর্ষ ব্র্যান্ডে সীমিত সময়ের অফার', 'https://images.unsplash.com/photo-1607082349566-187342175e2f?w=1200&h=600&fit=crop', '', '', 'Shop the Sale', 'সেলে কিনুন', '/flash-deals', '', '', '', 'rgba(220,38,38,0.3)', 'right', '#FFFFFF', 'Sale', 'সেল', 'destructive', 'fade', 700, 'xl', 'md', NULL, 1, 1, 1, 4, 1, '2025-01-01T00:00:00.000Z', '2025-01-01T00:00:00.000Z');

