INSERT OR IGNORE INTO blog_post (id, title, slug, excerpt, content, image, author, tags, published_at, is_published, created_at, updated_at) VALUES
('blog-001', 'iPhone 16 Pro Max: The Ultimate Review', 'iphone-16-pro-max-review', 'We take a deep dive into Apple''s latest flagship.', 'Apple has once again raised the bar with the iPhone 16 Pro Max. Featuring the A18 Pro chip, a 48MP camera system, and a stunning titanium design...', 'https://images.unsplash.com/photo-1695048133142-1a20484d2569?w=800&h=400&fit=crop', 'Tuktak Team', 'iPhone,Apple,Review', '2025-02-01T10:00:00.000Z', 1, '2025-02-01T10:00:00.000Z', '2025-02-01T10:00:00.000Z'),
('blog-002', 'Top 10 Gadgets Under ৳10,000', 'top-10-gadgets-under-10000', 'Best budget gadgets you can buy in Bangladesh right now.', 'Looking for amazing tech without breaking the bank? Here are our top picks for gadgets under ৳10,000...', 'https://images.unsplash.com/photo-1468495244123-6c6c332eeece?w=800&h=400&fit=crop', 'Tuktak Team', 'Gadgets,Budget,Bangladesh', '2025-03-15T10:00:00.000Z', 1, '2025-03-15T10:00:00.000Z', '2025-03-15T10:00:00.000Z'),
('blog-003', 'Samsung Galaxy S25 Ultra vs iPhone 16 Pro Max', 's25-ultra-vs-iphone-16-pro-max', 'The ultimate flagship showdown of 2025.', 'Two of the biggest names in smartphones go head to head. We compare design, camera, performance, and value...', 'https://images.unsplash.com/photo-1610945415295-d9bbf067e59c?w=800&h=400&fit=crop', 'Tuktak Team', 'Samsung,Apple,Comparison', '2025-02-20T10:00:00.000Z', 1, '2025-02-20T10:00:00.000Z', '2025-02-20T10:00:00.000Z'),
('blog-004', 'PS5 Pro: Is It Worth the Upgrade?', 'ps5-pro-worth-upgrade', 'We break down whether the PS5 Pro is worth your money.', 'Sony''s PS5 Pro promises 67% more GPU power and 2TB of storage. But is it worth upgrading from the standard PS5?', 'https://images.unsplash.com/photo-1606144042614-b2417e99c4e3?w=800&h=400&fit=crop', 'Tuktak Team', 'PS5,PlayStation,Gaming', '2025-04-01T10:00:00.000Z', 1, '2025-04-01T10:00:00.000Z', '2025-04-01T10:00:00.000Z');

