INSERT OR IGNORE INTO review (id, product_id, user_id, order_id, rating, title, body, is_approved, is_verified_purchase, created_at, updated_at) VALUES
('rev-001', 'prd-001', 'usr-002', 'ord-001', 5, 'Best iPhone ever!', 'The camera system is incredible. Battery life is amazing. Titanium design feels premium.', 1, 1, '2025-06-25T10:00:00.000Z', '2025-06-25T10:00:00.000Z'),
('rev-002', 'prd-009', 'usr-003', 'ord-002', 5, 'Noise cancellation is insane', 'Best headphones I have ever owned. The ANC blocks out everything. Comfortable for all day wear.', 1, 1, '2025-07-10T10:00:00.000Z', '2025-07-10T10:00:00.000Z'),
('rev-003', 'prd-012', 'usr-004', 'ord-003', 4, 'Great watch, steep price', 'Amazing fitness tracking and the GPS is super accurate. Battery lasts 3+ days easily.', 1, 1, '2025-07-25T10:00:00.000Z', '2025-07-25T10:00:00.000Z'),
('rev-004', 'prd-016', 'usr-004', NULL, 5, 'PS5 Pro is a beast', 'The graphics are insane. 4K 60fps on every game. Worth every penny.', 1, 0, '2025-07-20T10:00:00.000Z', '2025-07-20T10:00:00.000Z'),
('rev-005', 'prd-006', 'usr-002', NULL, 5, 'Ultimate work machine', 'M4 Max is ridiculously fast. Compiles in seconds. The display is gorgeous.', 1, 0, '2025-06-20T10:00:00.000Z', '2025-06-20T10:00:00.000Z'),
('rev-006', 'prd-002', 'usr-003', NULL, 4, 'S Pen is amazing', 'Best Android phone period. Camera is insane. S Pen makes it so productive.', 1, 0, '2025-07-05T10:00:00.000Z', '2025-07-05T10:00:00.000Z'),
('rev-007', 'prd-011', 'usr-005', NULL, 4, 'Great portable speaker', 'Sound quality is amazing for its size. Waterproof is a huge plus. Battery lasts forever.', 1, 0, '2025-08-01T10:00:00.000Z', '2025-08-01T10:00:00.000Z');

